import { useState, useEffect } from 'react';
import { Header } from './components/Header';
import { PromptStudio } from './components/PromptStudio';
import { CanvasViewer } from './components/CanvasViewer';
import { GalleryFilmstrip } from './components/GalleryFilmstrip';
import { ApiKeyModal } from './components/ApiKeyModal';
import { CodexView } from './components/CodexView';
import { OutlinerSplitView } from './components/Outliner/OutlinerSplitView';
import { AVAILABLE_MODELS, NOVEL_PRESETS } from './data/presets';
import { INITIAL_CODEX_ENTITIES, INITIAL_OUTLINER_NODES, INITIAL_OUTLINER_PATHWAYS } from './data/codexData';
import type { AppNavigationMode, ArtAsset, AspectRatio, CodexEntity, EngineProvider, GenerationStatus, OutlinerNode, OutlinerPathway, PresetItem } from './types';
import { executeArtGeneration, getStoredGeminiKey, getStoredHistory, getStoredPixaiKey } from './services/api';

export function App() {
  const [activeMode, setActiveMode] = useState<AppNavigationMode>('visual-studio');
  const [prompt, setPrompt] = useState(NOVEL_PRESETS[0].prompt);
  const [negativePrompt, setNegativePrompt] = useState(NOVEL_PRESETS[0].negativePrompt);
  const [aspectRatio, setAspectRatio] = useState<AspectRatio>(NOVEL_PRESETS[0].ratio);
  const [selectedProvider, setSelectedProvider] = useState<EngineProvider>('flux-free');
  const [selectedModelId, setSelectedModelId] = useState('flux-anime');
  const [activePresetId, setActivePresetId] = useState<string | null>(NOVEL_PRESETS[0].id);
  const [characterName, setCharacterName] = useState(NOVEL_PRESETS[0].character);

  const [codexEntities] = useState<CodexEntity[]>(INITIAL_CODEX_ENTITIES);
  const [outlinerNodes, setOutlinerNodes] = useState<OutlinerNode[]>(INITIAL_OUTLINER_NODES);
  const [pathways, setPathways] = useState<OutlinerPathway[]>(INITIAL_OUTLINER_PATHWAYS);

  const [currentAsset, setCurrentAsset] = useState<ArtAsset | null>(null);
  const [history, setHistory] = useState<ArtAsset[]>([]);
  const [status, setStatus] = useState<GenerationStatus>('idle');
  const [progress, setProgress] = useState(0);
  const [stepLabel, setStepLabel] = useState('');
  const [errorMessage, setErrorMessage] = useState('');

  const [hasGeminiKey, setHasGeminiKey] = useState(false);
  const [hasPixaiKey, setHasPixaiKey] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);

  const refreshKeys = () => {
    const gKey = Boolean(getStoredGeminiKey());
    const pKey = Boolean(getStoredPixaiKey());
    setHasGeminiKey(gKey);
    setHasPixaiKey(pKey);
  };

  useEffect(() => {
    refreshKeys();
    const saved = getStoredHistory();
    setHistory(saved);
    if (saved.length > 0) {
      setCurrentAsset(saved[0]);
    } else {
      // Preload initial asset for Raye
      setCurrentAsset({
        id: 'init_raye',
        prompt: NOVEL_PRESETS[0].prompt,
        negativePrompt: NOVEL_PRESETS[0].negativePrompt,
        modelId: 'flux-anime',
        modelName: 'Flux Anime Free Engine',
        aspectRatio: '2:3',
        imageUrl: NOVEL_PRESETS[0].previewUrl,
        createdAt: new Date().toISOString(),
        seed: 74829103,
        isLiveApi: true,
        provider: 'flux-free',
        character: 'Raye'
      });
    }
  }, []);

  const handleSelectPreset = (preset: PresetItem) => {
    setPrompt(preset.prompt);
    setNegativePrompt(preset.negativePrompt);
    setAspectRatio(preset.ratio);
    setActivePresetId(preset.id);
    setCharacterName(preset.character);
  };

  const handleGenerate = async (overrideProvider?: EngineProvider, overrideModelId?: string) => {
    const providerToUse = (typeof overrideProvider === 'string' ? overrideProvider : undefined) || selectedProvider;
    const modelToUse = (typeof overrideModelId === 'string' ? overrideModelId : undefined) || selectedModelId;
    if (!prompt.trim()) return;

    if (providerToUse === 'gemini-imagen' && !getStoredGeminiKey()) {
      setIsSettingsOpen(true);
      return;
    }

    setStatus('submitting');
    setProgress(5);
    setStepLabel('Initializing render...');
    setErrorMessage('');

    try {
      const selectedModel = AVAILABLE_MODELS.find((m) => m.id === modelToUse) || AVAILABLE_MODELS[0];
      const asset = await executeArtGeneration(
        prompt,
        negativePrompt,
        modelToUse,
        selectedModel.name,
        aspectRatio,
        characterName,
        providerToUse,
        (s, p, l) => {
          setStatus(s);
          setProgress(p);
          setStepLabel(l);
        }
      );

      setCurrentAsset(asset);
      setHistory(getStoredHistory());
      setStatus('completed');
    } catch (err: any) {
      console.error(err);
      setStatus('error');
      setErrorMessage(err.message || 'Generation failed.');
    }
  };

  const handleFallbackToFlux = () => {
    setSelectedProvider('flux-free');
    setSelectedModelId('flux-anime');
    handleGenerate('flux-free', 'flux-anime');
  };

  const handleSelectHistoryItem = (asset: ArtAsset) => {
    setCurrentAsset(asset);
    setPrompt(asset.prompt);
    setNegativePrompt(asset.negativePrompt);
    setAspectRatio(asset.aspectRatio);
    setSelectedModelId(asset.modelId);
    setSelectedProvider(asset.provider);
    if (asset.character) setCharacterName(asset.character);
  };

  const handleClearHistory = () => {
    localStorage.removeItem('omnitest_art_history');
    setHistory([]);
  };

  const handleForgeFromCodex = (presetId: string) => {
    const preset = NOVEL_PRESETS.find((p) => p.id === presetId);
    if (preset) {
      handleSelectPreset(preset);
      setActiveMode('visual-studio');
    }
  };

  const handleToggleFold = (nodeId: string) => {
    setOutlinerNodes((prev) =>
      prev.map((n) => (n.id === nodeId ? { ...n, isFolded: !n.isFolded } : n))
    );
  };

  const handleSelectPathway = (pathwayId: string) => {
    const selected = pathways.find((p) => p.id === pathwayId);
    if (!selected) return;

    setPathways((prev) =>
      prev.map((p) => ({ ...p, isSelected: p.id === pathwayId }))
    );

    const newChapterNum = outlinerNodes.length + 1;
    const newNode: OutlinerNode = {
      id: `ch-${newChapterNum}`,
      actTitle: 'Act I: The Machine & The Breach',
      chapterNumber: newChapterNum,
      title: selected.title.replace(/^Trajectory [A-Za-z]+:\s*/, ''),
      oneLineSummary: selected.trajectory,
      beats: selected.beats,
      keyCharacters: ['Deus', 'Raye'],
      location: 'Syndicate Ground Zero',
      isFolded: false,
      status: 'canon'
    };

    setOutlinerNodes((prev) => [...prev, newNode]);
  };

  const handleAddNode = () => {
    const newChapterNum = outlinerNodes.length + 1;
    const newNode: OutlinerNode = {
      id: `ch-${newChapterNum}`,
      actTitle: 'Act II: The Sovereign Syndicate',
      chapterNumber: newChapterNum,
      title: `Chapter ${newChapterNum}: The Midnight Breach`,
      oneLineSummary: 'Deus and Raye execute their joint operation under heavy rain.',
      beats: [
        'Entry through compromised maintenance ducts.',
        'Tactical banter while disabling secondary security grids.',
        'High-stakes standoff at the central data core.'
      ],
      keyCharacters: ['Deus', 'Raye'],
      location: 'Central Data Core',
      isFolded: false,
      status: 'draft'
    };
    setOutlinerNodes((prev) => [...prev, newNode]);
  };

  return (
    <div className="app-container">
      <Header
        hasGeminiKey={hasGeminiKey}
        hasPixaiKey={hasPixaiKey}
        activeProvider={selectedProvider}
        activeMode={activeMode}
        onModeChange={setActiveMode}
        onOpenSettings={() => setIsSettingsOpen(true)}
      />

      {activeMode === 'visual-studio' && (
        <main className="studio-layout">
          <PromptStudio
            prompt={prompt}
            setPrompt={setPrompt}
            negativePrompt={negativePrompt}
            setNegativePrompt={setNegativePrompt}
            aspectRatio={aspectRatio}
            setAspectRatio={setAspectRatio}
            selectedModelId={selectedModelId}
            setSelectedModelId={setSelectedModelId}
            models={AVAILABLE_MODELS}
            presets={NOVEL_PRESETS}
            onSelectPreset={handleSelectPreset}
            onGenerate={() => handleGenerate()}
            isGenerating={['submitting', 'queued', 'denoising', 'decoding'].includes(status)}
            activePresetId={activePresetId}
            selectedProvider={selectedProvider}
            setSelectedProvider={setSelectedProvider}
          />

          <div style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
            <CanvasViewer
              currentAsset={currentAsset}
              status={status}
              progress={progress}
              stepLabel={stepLabel}
              errorMessage={errorMessage}
              onFallbackToFlux={handleFallbackToFlux}
            />

            <GalleryFilmstrip
              history={history}
              selectedId={currentAsset?.id || null}
              onSelect={handleSelectHistoryItem}
              onClear={handleClearHistory}
            />
          </div>
        </main>
      )}

      {activeMode === 'novel-codex' && (
        <main style={{ maxWidth: '1440px', margin: '0 auto', padding: '24px 20px', width: '100%' }}>
          <CodexView entities={codexEntities} onForgeEntity={handleForgeFromCodex} />
        </main>
      )}

      {activeMode === 'narrative-outliner' && (
        <main style={{ maxWidth: '1440px', margin: '0 auto', padding: '24px 20px', width: '100%' }}>
          <OutlinerSplitView
            nodes={outlinerNodes}
            pathways={pathways}
            onSelectPathway={handleSelectPathway}
            onToggleFold={handleToggleFold}
            onAddNode={handleAddNode}
          />
        </main>
      )}

      <ApiKeyModal
        isOpen={isSettingsOpen}
        onClose={() => setIsSettingsOpen(false)}
        onKeysUpdated={refreshKeys}
      />
    </div>
  );
}

export default App;

