  speakerB: string;
  lineB: string;
  subtext: string;
}

export interface WritingPromptItem {
  id: string;
  title: string;
  category: PromptCategory;
  categoryLabel: string;
  tagline: string;
  characterFocus: 'Duo' | 'Raye' | 'Deus' | 'World';
  imageUrl: string;
  accentColor: string;
  hook: string;
  sensoryAnchors: SensoryAnchors;
  dialogueSpar: DialogueSpar;
  guidingQuestions: string[];
  artPrompt: string;
  negativePrompt?: string;
  aspectRatio: AspectRatio;
}

export type CodexCategory = 'character' | 'faction' | 'technology' | 'location';

