import React from 'react';
import { GitBranch, ChevronDown, ChevronUp, Check, Plus, Zap, Layers } from 'lucide-react';
import type { OutlinerNode, OutlinerPathway } from '../../types';

interface OutlinerSplitViewProps {
  nodes: OutlinerNode[];
  pathways: OutlinerPathway[];
  onSelectPathway: (pathwayId: string) => void;
  onToggleFold: (nodeId: string) => void;
  onAddNode: () => void;
}

export const OutlinerSplitView: React.FC<OutlinerSplitViewProps> = ({
  nodes,
  pathways,
  onSelectPathway,
  onToggleFold,
  onAddNode
}) => {

  const getConflictColor = (type: OutlinerPathway['conflictType']) => {
    switch (type) {
      case 'infiltrative': return '#00f0ff';
      case 'psychological': return '#ff2a85';
      case 'cyber': return '#a855f7';
      case 'kinetic': return '#f59e0b';
    }
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '32px' }}>
      {/* Zone 1: Determined Past Spine Header */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
          <div style={{
            width: '36px',
            height: '36px',
            borderRadius: '10px',
            background: 'rgba(0, 240, 255, 0.1)',
            border: '1px solid rgba(0, 240, 255, 0.3)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center'
          }}>
            <Layers size={18} color="#00f0ff" />
          </div>
          <div>
            <h2 style={{ fontFamily: 'var(--font-heading)', fontSize: '1.4rem', color: '#fff' }}>
              Zone 1: Determined Past Spine (Canon Chronology)
            </h2>
            <div style={{ fontSize: '0.8rem', color: 'var(--text-muted)' }}>
              Sequential fixed reality • 1-Click summary folding enabled
            </div>
          </div>
        </div>

        <button
          type="button"
          className="btn-ghost"
          style={{ minHeight: '44px', padding: '0 18px', gap: '8px' }}

