import React, { useState } from 'react';
import {
  Sparkles,
  Shuffle,
  Eye,
  Volume2,
  Hand,
  Wind,
  MessageSquare,
  HelpCircle,
  Palette,
  Copy,
  Check,
  Send,
  Search,
  Filter
} from 'lucide-react';
import type { PromptCategory, WritingPromptItem } from '../types';

interface WritingPromptsViewProps {
  prompts: WritingPromptItem[];
  onForgeVisual: (artPrompt: string, negativePrompt?: string, ratio?: any, character?: string) => void;
  onSendToOutliner?: (prompt: WritingPromptItem) => void;
}

export const WritingPromptsView: React.FC<WritingPromptsViewProps> = ({
  prompts,
  onForgeVisual,
  onSendToOutliner
}) => {
  const [selectedCategory, setSelectedCategory] = useState<PromptCategory>('all');
  const [selectedCharacter, setSelectedCharacter] = useState<'All' | 'Duo' | 'Raye' | 'Deus' | 'World'>('All');
  const [searchQuery, setSearchQuery] = useState('');
  const [activePromptId, setActivePromptId] = useState<string>(prompts[0]?.id || '');
  const [copied, setCopied] = useState(false);
  const [outlinerAdded, setOutlinerAdded] = useState(false);

  const filteredPrompts = prompts.filter((item) => {
    const matchesCategory = selectedCategory === 'all' || item.category === selectedCategory;
    const matchesCharacter = selectedCharacter === 'All' || item.characterFocus === selectedCharacter;
    const q = searchQuery.toLowerCase().trim();
    const matchesSearch = !q || (
      item.title.toLowerCase().includes(q) ||
      item.tagline.toLowerCase().includes(q) ||
      item.hook.toLowerCase().includes(q) ||
      item.categoryLabel.toLowerCase().includes(q)
    );
    return matchesCategory && matchesCharacter && matchesSearch;
  });

  const activePrompt = prompts.find((p) => p.id === activePromptId) || filteredPrompts[0] || prompts[0];

  const handleSurpriseMe = () => {
    if (prompts.length === 0) return;
    const randomIndex = Math.floor(Math.random() * prompts.length);
    const chosen = prompts[randomIndex];
    setActivePromptId(chosen.id);
  };

  const handleCopyBrief = () => {
    if (!activePrompt) return;
    const briefText = [
      `PROMPT: ${activePrompt.title} [${activePrompt.categoryLabel}]`,
      `CHARACTER FOCUS: ${activePrompt.characterFocus}`,
      `TAGLINE: ${activePrompt.tagline}`,
      '',
      `CATALYST HOOK:`,
      activePrompt.hook,
      '',
      `DIALOGUE SPAR:`,
      `${activePrompt.dialogueSpar.speakerA}: "${activePrompt.dialogueSpar.lineA}"`,
      `${activePrompt.dialogueSpar.speakerB}: "${activePrompt.dialogueSpar.lineB}"`,
      `[Subtext: ${activePrompt.dialogueSpar.subtext}]`,
      '',
      `SENSORY ANCHORS:`,
      `- Sight: ${activePrompt.sensoryAnchors.sight}`,
      `- Sound: ${activePrompt.sensoryAnchors.sound}`,
      `- Tactile: ${activePrompt.sensoryAnchors.tactile}`,
      `- Atmosphere: ${activePrompt.sensoryAnchors.scentOrAtmosphere}`,
      '',
      `GUIDING QUESTIONS:`,
      ...activePrompt.guidingQuestions.map((q, idx) => `${idx + 1}. ${q}`)
    ].join('\n');

    navigator.clipboard.writeText(briefText);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleSendToOutliner = () => {
    if (!activePrompt || !onSendToOutliner) return;
    onSendToOutliner(activePrompt);
    setOutlinerAdded(true);
    setTimeout(() => setOutlinerAdded(false), 2000);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '24px', maxWidth: '1440px', margin: '0 auto', width: '100%' }}>
      {/* Top Banner & Control Deck */}
      <div className="glass-panel" style={{ padding: '24px', display: 'flex', flexDirection: 'column', gap: '20px' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '16px' }}>
          <div>
            <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
              <div style={{
                width: '36px',
                height: '36px',
                borderRadius: '10px',
                background: 'linear-gradient(135deg, rgba(168, 85, 247, 0.2), rgba(0, 240, 255, 0.2))',
                border: '1px solid rgba(168, 85, 247, 0.4)',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center'
              }}>
                <Sparkles size={18} color="#a855f7" />
              </div>
              <h2 style={{ fontFamily: 'var(--font-heading)', fontSize: '1.4rem', color: '#fff' }}>
                Visual Writing Prompts & Idea Sparks
              </h2>
            </div>
            <div style={{ fontSize: '0.82rem', color: 'var(--text-muted)', marginTop: '4px' }}>
              Atmospheric sensory anchors, dialogue spars, and narrative catalysts paired with visual scene artwork.
            </div>
          </div>

          <div style={{ display: 'flex', gap: '10px' }}>
            <button
              type="button"
              className="btn-ghost"
              style={{
                minHeight: '44px',
                padding: '0 18px',
                gap: '8px',
                background: 'rgba(168, 85, 247, 0.12)',
                borderColor: 'rgba(168, 85, 247, 0.4)',
                color: '#c084fc'
              }}
              onClick={handleSurpriseMe}
            >
              <Shuffle size={16} />
              <span>Surprise Me (Random Spark)</span>
            </button>
          </div>
        </div>

        {/* Filter Controls Row */}
        <div style={{ display: 'flex', gap: '16px', alignItems: 'center', flexWrap: 'wrap' }}>
          {/* Search Bar */}
          <div style={{
            position: 'relative',
            flex: '1 1 240px',
            minHeight: '44px'
          }}>
            <Search size={16} color="var(--text-dim)" style={{ position: 'absolute', left: '14px', top: '14px' }} />
            <input
              type="text"
              placeholder="Filter writing prompts by keyword or theme..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              style={{
                width: '100%',
                height: '44px',
                paddingLeft: '40px',
                paddingRight: '14px',
                borderRadius: 'var(--radius-md)',
                background: 'var(--bg-input)',
                border: '1px solid var(--border-subtle)',
                color: 'var(--text-main)',
                fontSize: '0.85rem',
                outline: 'none'
              }}
            />
          </div>

          {/* Character Focus Buttons */}
          <div style={{ display: 'flex', gap: '6px', background: 'var(--bg-input)', padding: '4px', borderRadius: 'var(--radius-md)' }}>
            {(['All', 'Duo', 'Raye', 'Deus', 'World'] as const).map((char) => (
              <button
                key={char}
                type="button"
                className="btn-ghost"
                style={{
                  minHeight: '36px',
                  padding: '0 12px',
                  fontSize: '0.75rem',
                  background: selectedCharacter === char ? 'var(--bg-active)' : 'transparent',
                  borderColor: selectedCharacter === char ? 'var(--accent-cyan)' : 'transparent',
                  color: selectedCharacter === char ? 'var(--accent-cyan)' : 'var(--text-muted)'
                }}
                onClick={() => setSelectedCharacter(char)}
              >
                {char}
              </button>
            ))}
          </div>
        </div>

        {/* Category Filter Pills */}
        <div style={{ display: 'flex', gap: '8px', overflowX: 'auto', paddingBottom: '4px' }}>
          {([
            { id: 'all', label: 'All Sparks' },
            { id: 'dialogue-banter', label: 'Dialogue & Banter' },
            { id: 'sensory-hooks', label: 'Sensory Hooks' },
            { id: 'ticking-clock', label: 'Ticking Clock' },
            { id: 'vulnerability', label: 'Vulnerability & Cracks' },
            { id: 'tactical-action', label: 'Tactical Action' },
            { id: 'worldbuilding-twists', label: 'Worldbuilding Twists' }
          ] as const).map((cat) => (
            <button
              key={cat.id}
              type="button"
              className="btn-ghost"
              style={{
                minHeight: '38px',
                padding: '0 14px',
                fontSize: '0.78rem',
                borderRadius: '999px',
                whiteSpace: 'nowrap',
                background: selectedCategory === cat.id ? 'rgba(0, 240, 255, 0.12)' : 'rgba(255, 255, 255, 0.03)',
                borderColor: selectedCategory === cat.id ? 'var(--accent-cyan)' : 'var(--border-subtle)',
                color: selectedCategory === cat.id ? 'var(--accent-cyan)' : 'var(--text-muted)'
              }}
              onClick={() => setSelectedCategory(cat.id)}
            >
              <Filter size={12} style={{ opacity: selectedCategory === cat.id ? 1 : 0.5 }} />
              <span>{cat.label}</span>
            </button>
          ))}
        </div>
      </div>

      {/* Main Split Grid: Prompt List & Active Prompt Deep Dive */}
      <div style={{ display: 'grid', gridTemplateColumns: '380px 1fr', gap: '24px', alignItems: 'start' }}>
        {/* Left Side: Prompts Cards List */}
        <div className="glass-panel" style={{ padding: '16px', display: 'flex', flexDirection: 'column', gap: '12px', maxHeight: '820px', overflowY: 'auto' }}>
          <div style={{ fontSize: '0.75rem', fontWeight: 700, textTransform: 'uppercase', color: 'var(--text-dim)', paddingLeft: '4px' }}>
            Showing {filteredPrompts.length} Spark Prompts
          </div>

          {filteredPrompts.map((item) => {
            const isSelected = activePrompt?.id === item.id;
            return (
              <div
                key={item.id}
                onClick={() => setActivePromptId(item.id)}
                style={{
                  display: 'flex',
                  gap: '12px',
                  padding: '12px',
                  borderRadius: 'var(--radius-md)',
                  background: isSelected ? 'rgba(0, 240, 255, 0.08)' : 'rgba(255, 255, 255, 0.02)',
                  border: `1px solid ${isSelected ? item.accentColor : 'var(--border-subtle)'}`,
                  cursor: 'pointer',
                  transition: 'all 0.2s ease'
                }}
              >
                <div style={{
                  width: '74px',
                  height: '74px',
                  borderRadius: '8px',
                  overflow: 'hidden',
                  flexShrink: 0,
                  position: 'relative'
                }}>
                  <img
                    src={item.imageUrl}
                    alt={item.title}
                    style={{ width: '100%', height: '100%', objectFit: 'cover' }}
                  />
                  <div style={{
                    position: 'absolute',
                    top: '4px',
                    left: '4px',
                    fontSize: '0.6rem',
                    fontWeight: 700,
                    padding: '2px 6px',
                    borderRadius: '4px',
                    background: 'rgba(0, 0, 0, 0.75)',
                    color: item.accentColor
                  }}>
                    {item.characterFocus}
                  </div>
                </div>

                <div style={{ display: 'flex', flexDirection: 'column', justifyContent: 'center', minWidth: 0, flex: 1 }}>
                  <div style={{ fontSize: '0.7rem', color: item.accentColor, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.04em' }}>
                    {item.categoryLabel}
                  </div>
                  <div style={{ fontSize: '0.92rem', fontWeight: 700, color: '#fff', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', marginTop: '2px' }}>
                    {item.title}
                  </div>
                  <div style={{ fontSize: '0.74rem', color: 'var(--text-muted)', display: '-webkit-box', WebkitLineClamp: 2, WebkitBoxOrient: 'vertical', overflow: 'hidden', marginTop: '3px', lineHeight: '1.25' }}>
                    {item.tagline}
                  </div>
                </div>
              </div>
            );
          })}
        </div>

        {/* Right Side: Deep Dive Scene Inspector */}
        {activePrompt && (
          <div className="glass-panel" style={{ padding: '24px', display: 'flex', flexDirection: 'column', gap: '22px' }}>
            {/* Visual Hero & Action Bar */}
            <div style={{
              position: 'relative',
              borderRadius: 'var(--radius-lg)',
              overflow: 'hidden',
              height: '240px',
              border: `1px solid ${activePrompt.accentColor}`
            }}>
              <img
                src={activePrompt.imageUrl}
                alt={activePrompt.title}
                style={{ width: '100%', height: '100%', objectFit: 'cover', filter: 'brightness(0.65)' }}
              />
              <div style={{
                position: 'absolute',
                inset: 0,
                background: 'linear-gradient(to top, rgba(7, 9, 14, 0.95) 15%, transparent 80%)',
                display: 'flex',
                flexDirection: 'column',
                justifyContent: 'flex-end',
                padding: '20px'
              }}>
                <div style={{ display: 'flex', gap: '8px', alignItems: 'center', marginBottom: '6px' }}>
                  <span style={{
                    fontSize: '0.7rem',
                    fontWeight: 700,
                    textTransform: 'uppercase',
                    padding: '3px 10px',
                    borderRadius: '999px',
                    background: activePrompt.accentColor,
                    color: '#000'
                  }}>
                    {activePrompt.categoryLabel}
                  </span>
                  <span style={{
                    fontSize: '0.7rem',
                    fontWeight: 700,
                    padding: '3px 10px',
                    borderRadius: '999px',
                    background: 'rgba(255, 255, 255, 0.15)',
                    color: '#fff'
                  }}>
                    Focus: {activePrompt.characterFocus}
                  </span>
                </div>
                <h3 style={{ fontFamily: 'var(--font-heading)', fontSize: '1.6rem', color: '#fff', fontWeight: 800 }}>
                  {activePrompt.title}
                </h3>
                <div style={{ fontSize: '0.85rem', color: 'var(--text-muted)' }}>
                  {activePrompt.tagline}
                </div>
              </div>

              {/* 1-Click Action Buttons Floated on Hero */}
              <div style={{ position: 'absolute', top: '16px', right: '16px', display: 'flex', gap: '8px' }}>
                <button
                  type="button"
                  className="btn-ghost"
                  style={{
                    minHeight: '40px',
                    padding: '0 14px',
                    background: 'rgba(0, 0, 0, 0.75)',
                    borderColor: 'var(--accent-cyan)',
                    color: 'var(--accent-cyan)',
                    backdropFilter: 'blur(8px)'
                  }}
                  onClick={() => onForgeVisual(activePrompt.artPrompt, activePrompt.negativePrompt, activePrompt.aspectRatio, activePrompt.characterFocus)}
                  title="Load image prompt into Visual Studio generator"
                >
                  <Palette size={15} />
                  <span>Forge in Visual Studio</span>
                </button>
              </div>
            </div>

            {/* Catalyst Hook */}
            <div style={{
              padding: '16px 20px',
              borderRadius: 'var(--radius-md)',
              background: 'rgba(0, 240, 255, 0.05)',
              borderLeft: `4px solid ${activePrompt.accentColor}`
            }}>
              <div style={{ fontSize: '0.72rem', fontWeight: 800, textTransform: 'uppercase', color: activePrompt.accentColor, letterSpacing: '0.06em', marginBottom: '6px' }}>
                The Catalyst Hook (Scene Premise)
              </div>
              <div style={{ fontSize: '0.94rem', color: '#fff', lineHeight: 1.6, fontStyle: 'italic' }}>
                "{activePrompt.hook}"
              </div>
            </div>

            {/* Dialogue Spar Duel */}
            <div style={{
              background: 'var(--bg-input)',
              padding: '18px',
              borderRadius: 'var(--radius-md)',
              border: '1px solid var(--border-subtle)',
              display: 'flex',
              flexDirection: 'column',
              gap: '12px'
            }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                <MessageSquare size={16} color="var(--accent-rose)" />
                <span style={{ fontSize: '0.78rem', fontWeight: 700, textTransform: 'uppercase', color: 'var(--text-muted)', letterSpacing: '0.05em' }}>
                  Character Dialogue Spar & Subtext
                </span>
              </div>

              <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
                <div style={{ display: 'flex', gap: '10px', alignItems: 'flex-start' }}>
                  <div style={{
                    fontSize: '0.75rem',
                    fontWeight: 700,
                    padding: '3px 8px',
                    borderRadius: '4px',
                    background: activePrompt.dialogueSpar.speakerA === 'Raye' ? 'rgba(255, 42, 133, 0.15)' : 'rgba(0, 240, 255, 0.15)',
                    color: activePrompt.dialogueSpar.speakerA === 'Raye' ? 'var(--accent-rose)' : 'var(--accent-cyan)',
                    minWidth: '60px',
                    textAlign: 'center'
                  }}>
                    {activePrompt.dialogueSpar.speakerA}
                  </div>
                  <div style={{ fontSize: '0.88rem', color: '#fff', flex: 1, lineHeight: 1.4 }}>
                    "{activePrompt.dialogueSpar.lineA}"
                  </div>
                </div>

                <div style={{ display: 'flex', gap: '10px', alignItems: 'flex-start' }}>
                  <div style={{
                    fontSize: '0.75rem',
                    fontWeight: 700,
                    padding: '3px 8px',
                    borderRadius: '4px',
                    background: activePrompt.dialogueSpar.speakerB === 'Raye' ? 'rgba(255, 42, 133, 0.15)' : 'rgba(0, 240, 255, 0.15)',
                    color: activePrompt.dialogueSpar.speakerB === 'Raye' ? 'var(--accent-rose)' : 'var(--accent-cyan)',
                    minWidth: '60px',
                    textAlign: 'center'
                  }}>
                    {activePrompt.dialogueSpar.speakerB}
                  </div>
                  <div style={{ fontSize: '0.88rem', color: '#fff', flex: 1, lineHeight: 1.4 }}>
                    "{activePrompt.dialogueSpar.lineB}"
                  </div>
                </div>

                <div style={{
                  fontSize: '0.75rem',
                  color: 'var(--text-dim)',
                  borderTop: '1px solid rgba(255, 255, 255, 0.05)',
                  paddingTop: '8px',
                  fontStyle: 'italic'
                }}>
                  Subtext: {activePrompt.dialogueSpar.subtext}
                </div>
              </div>
            </div>

            {/* Sensory Anchors Matrix */}
            <div>
              <div style={{ fontSize: '0.78rem', fontWeight: 700, textTransform: 'uppercase', color: 'var(--text-muted)', letterSpacing: '0.05em', marginBottom: '10px' }}>
                Sensory Anchors (Descriptive Concrete Details)
              </div>
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2, 1fr)', gap: '10px' }}>
                <div style={{ background: 'var(--bg-input)', padding: '12px 14px', borderRadius: 'var(--radius-md)', border: '1px solid var(--border-subtle)' }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '6px', color: '#00f0ff', fontSize: '0.75rem', fontWeight: 700, marginBottom: '4px' }}>
                    <Eye size={14} /> <span>SIGHT</span>
                  </div>
                  <div style={{ fontSize: '0.8rem', color: 'var(--text-main)', lineHeight: 1.4 }}>
                    {activePrompt.sensoryAnchors.sight}
                  </div>
                </div>

                <div style={{ background: 'var(--bg-input)', padding: '12px 14px', borderRadius: 'var(--radius-md)', border: '1px solid var(--border-subtle)' }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '6px', color: '#ff2a85', fontSize: '0.75rem', fontWeight: 700, marginBottom: '4px' }}>
                    <Volume2 size={14} /> <span>SOUND</span>
                  </div>
                  <div style={{ fontSize: '0.8rem', color: 'var(--text-main)', lineHeight: 1.4 }}>
                    {activePrompt.sensoryAnchors.sound}
                  </div>
                </div>

                <div style={{ background: 'var(--bg-input)', padding: '12px 14px', borderRadius: 'var(--radius-md)', border: '1px solid var(--border-subtle)' }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '6px', color: '#f59e0b', fontSize: '0.75rem', fontWeight: 700, marginBottom: '4px' }}>
                    <Hand size={14} /> <span>TACTILE</span>
                  </div>
                  <div style={{ fontSize: '0.8rem', color: 'var(--text-main)', lineHeight: 1.4 }}>
                    {activePrompt.sensoryAnchors.tactile}
                  </div>
                </div>

                <div style={{ background: 'var(--bg-input)', padding: '12px 14px', borderRadius: 'var(--radius-md)', border: '1px solid var(--border-subtle)' }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '6px', color: '#10b981', fontSize: '0.75rem', fontWeight: 700, marginBottom: '4px' }}>
                    <Wind size={14} /> <span>ATMOSPHERE</span>
                  </div>
                  <div style={{ fontSize: '0.8rem', color: 'var(--text-main)', lineHeight: 1.4 }}>
                    {activePrompt.sensoryAnchors.scentOrAtmosphere}
                  </div>
                </div>
              </div>
            </div>

            {/* Guiding Questions */}
            <div style={{ background: 'var(--bg-input)', padding: '16px', borderRadius: 'var(--radius-md)', border: '1px solid var(--border-subtle)' }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: '6px', color: '#a855f7', fontSize: '0.78rem', fontWeight: 700, textTransform: 'uppercase', marginBottom: '8px' }}>
                <HelpCircle size={15} /> <span>Guiding Questions to Write the Scene</span>
              </div>
              <ul style={{ paddingLeft: '18px', display: 'flex', flexDirection: 'column', gap: '6px' }}>
                {activePrompt.guidingQuestions.map((q, idx) => (
                  <li key={idx} style={{ fontSize: '0.82rem', color: 'var(--text-main)', lineHeight: 1.4 }}>
                    {q}
                  </li>
                ))}
              </ul>
            </div>

            {/* Bottom Actions Row */}
            <div style={{ display: 'flex', gap: '12px', justifyContent: 'flex-end', flexWrap: 'wrap', paddingTop: '8px' }}>
              <button
                type="button"
                className="btn-ghost"
                style={{ minHeight: '44px', padding: '0 18px', gap: '8px' }}
                onClick={handleCopyBrief}
              >
                {copied ? <Check size={16} color="#10b981" /> : <Copy size={16} />}
                <span>{copied ? 'Scene Brief Copied!' : 'Copy Scene Brief'}</span>
              </button>

              {onSendToOutliner && (
                <button
                  type="button"
                  className="btn-ghost"
                  style={{ minHeight: '44px', padding: '0 18px', gap: '8px', color: outlinerAdded ? '#10b981' : 'var(--text-main)' }}
                  onClick={handleSendToOutliner}
                >
                  {outlinerAdded ? <Check size={16} color="#10b981" /> : <Send size={16} />}
                  <span>{outlinerAdded ? 'Sent to Outliner!' : 'Send to Narrative Outliner'}</span>
                </button>
              )}

              <button
                type="button"
                className="btn-ghost"
                style={{
                  minHeight: '44px',
                  padding: '0 20px',
                  gap: '8px',
                  background: 'linear-gradient(135deg, rgba(0, 240, 255, 0.2), rgba(168, 85, 247, 0.2))',
                  borderColor: 'var(--accent-cyan)',
                  color: '#fff',
                  fontWeight: 700
                }}
                onClick={() => onForgeVisual(activePrompt.artPrompt, activePrompt.negativePrompt, activePrompt.aspectRatio, activePrompt.characterFocus)}
              >
                <Palette size={16} color="#00f0ff" />
                <span>Forge Scene Artwork</span>
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

